import raw from './emoji.json';

export interface Emoji {
  category: EmojiCategory;
  emoji: string;
  shortname: string;
  /** Other shortnames the same emoji goes by. */
  keywords: string[];
}

/** In the order the picker shows them; the i18n key is `emoji.category.<name>`. */
export const EMOJI_CATEGORIES = [
  'smileys',
  'people',
  'nature',
  'food',
  'activity',
  'travel',
  'objects',
  'symbols',
  'flags',
] as const;
export type EmojiCategory = (typeof EMOJI_CATEGORIES)[number];

/** Generated by `scripts/trim-emoji.mjs` from Converse's emoji.json; do not edit by hand. */
export const EMOJIS: Emoji[] = raw as Emoji[];

function byShortname(shortname: string): Emoji {
  const entry = EMOJIS.find((candidate) => candidate.shortname === shortname);
  if (!entry) throw new Error(`Quick emoji ${shortname} missing from emoji.json`);
  return entry;
}

/** The six a reaction is most often made of, for the quick row; the shortname names the button. */
export const QUICK_EMOJIS: Emoji[] = ['thumbsup', 'heart', 'joy', 'open_mouth', 'cry', 'pray'].map(
  byShortname,
);

/** A letter's toolbar offers three emojis before "React": the viewer's most used, else these. */
const TOOLBAR_DEFAULTS: Emoji[] = ['thumbsup', 'heart', 'joy'].map(byShortname);

/** The `count` emojis used most (ties: the first counted), filled up with the defaults. */
export function favouriteEmojis(usage: Record<string, number>, count = 3): Emoji[] {
  const used = Object.entries(usage)
    .sort((a, b) => b[1] - a[1])
    .map(([emoji]) => EMOJIS.find((entry) => entry.emoji === emoji))
    .filter((entry): entry is Emoji => entry !== undefined);
  const chosen: Emoji[] = [];
  for (const entry of [...used, ...TOOLBAR_DEFAULTS]) {
    if (chosen.length === count) break;
    if (!chosen.includes(entry)) chosen.push(entry);
  }
  return chosen;
}

/** Emojis whose shortname or keywords contain the query (spaces read as underscores). */
export function searchEmojis(query: string, list: Emoji[] = EMOJIS): Emoji[] {
  const needle = query.trim().toLowerCase().replace(/\s+/g, '_');
  if (!needle) return list;
  return list.filter(
    (entry) =>
      entry.shortname.includes(needle) || entry.keywords.some((word) => word.includes(needle)),
  );
}

/**
 * What `:query` completes to in the composer: the shortnames that start with it first, shortest
 * first (`:smile` before `:smiley`), then those that contain it (or whose keywords do), at most
 * `limit`.
 */
export function suggestEmojis(query: string, limit = 8): Emoji[] {
  const needle = query.toLowerCase();
  const found = searchEmojis(needle);
  const starting = found
    .filter((entry) => entry.shortname.startsWith(needle))
    .sort((a, b) => a.shortname.length - b.shortname.length);
  const others = found.filter((entry) => !entry.shortname.startsWith(needle));
  return [...starting, ...others].slice(0, limit);
}
